module shuffle_count(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] a [0:7],\n    input [2:0] b [0:7],\n    output reg [7:0] result,\n    output reg done\n);\n    // State declarations\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] COMP_A_INV   = 4'd1;\n    localparam [3:0] COMP_X       = 4'd2;\n    localparam [3:0] FIND_ORDER   = 4'd3;\n    localparam [3:0] FIND_D       = 4'd4;\n    localparam [3:0] COMPUTE_RESULT = 4'd5;\n    localparam [3:0] DONE_STATE   = 4'd6;\n    reg [3:0] state, next_state;\n    \n    // Internal arrays\n    reg [2:0] a_inv [0:7];    // Inverse of A\n    reg [2:0] x_reg [0:7];    // X = B ∘ A\n    reg [2:0] current_power [0:7];\n    reg [2:0] next_power [0:7];\n    \n    // Counters\n    reg [4:0] cycle_counter;\n    reg [3:0] i, j, k, l;     // Loop variables\n    \n    // Results\n    reg [7:0]    L;           // Order of X\n    reg [7:0]    d_reg;\n    reg          d_found;\n    \n    // Temporary variables\n    reg          match;\n    reg [7:0]    even_candidate, odd_candidate;\n    \n    // Finite State Machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 8'd0;\n            done <= 1'b0;\n            cycle_counter <= 5'd0;\n            d_reg <= 8'd0;\n            d_found <= 1'b0;\n            // Array initialization\n            for (k = 0; k < 8; k = k + 1) begin\n                a_inv[k] <= 3'd0;\n                x_reg[k] <= 3'd0;\n                current_power[k] <= 3'd0;\n                next_power[k] <= 3'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 5'd0;\n                    d_found <= 1'b0;\n                    d_reg <= 8'd0;\n                    l <= 4'd0;\n                    if (start) begin\n                        state <= COMP_A_INV;\n                    end\n                end\n                \n                COMP_A_INV: begin\n                    // Compute A_inv by inversion\n                    for (i = 0; i < 8; i = i + 1) begin : comp_ainv\n                        a_inv[a[i]] <= i;\n                    end\n                    state <= COMP_X;\n                end\n                \n                COMP_X: begin\n                    // Compute X = B ∘ A (X[i] = B[A[i]])\n                    for (i = 0; i < 8; i = i + 1) begin\n                        x_reg[i] <= b[a[i]];\n                    end\n                    // Initialize current_power as identity\n                    for (i = 0; i < 8; i = i + 1) begin\n                        current_power[i] <= i;\n                    end\n                    L <= 8'd0;\n                    cycle_counter <= 5'd0;\n                    state <= FIND_ORDER;\n                end\n                \n                FIND_ORDER: begin\n                    // Check if current_power is identity\n                    match = 1'b1;\n                    for (j = 0; j < 8; j = j + 1) begin\n                        if (current_power[j] != j) match = 1'b0;\n                    end\n                    \n                    if (cycle_counter != 0 && match) begin\n                        L <= cycle_counter;\n                        // Reset current_power to identity for FIND_D state\n                        for (j = 0; j < 8; j = j + 1) begin\n                            current_power[j] <= j;\n                        end\n                        cycle_counter <= 5'd0;\n                        state <= FIND_D;\n                    end else begin\n                        // Compose X with current_power (next_power = X ∘ current_power)\n                        for (j = 0; j < 8; j = j + 1) begin\n                            next_power[j] <= x_reg[current_power[j]];\n                        end\n                        // Update current_power and counters\n                        for (j = 0; j < 8; j = j + 1) begin\n                            current_power[j] <= next_power[j];\n                        end\n                        cycle_counter <= cycle_counter + 5'd1;\n                        if (cycle_counter > 5'd16) begin\n                            // Fallback in case of error\n                            L <= 8'd16;\n                            state <= FIND_D;\n                        end\n                    end\n                end\n                \n                FIND_D: begin\n                    // Check if current_power == A_inv\n                    match = 1'b1;\n                    for (j = 0; j < 8; j = j + 1) begin\n                        if (current_power[j] != a_inv[j]) match = 1'b0;\n                    end\n                    \n                    if (match) begin\n                        d_reg <= cycle_counter;\n                        d_found <= 1'b1;\n                        state <= COMPUTE_RESULT;\n                    end else if (cycle_counter >= L) begin\n                        state <= COMPUTE_RESULT;\n                    end else begin\n                        // Compose X with current_power\n                        for (j = 0; j < 8; j = j + 1) begin\n                            next_power[j] <= x_reg[current_power[j]];\n                        end\n                        // Update current_power\n                        for (j = 0; j < 8; j = j + 1) begin\n                            current_power[j] <= next_power[j];\n                        end\n                        cycle_counter <= cycle_counter + 5'd1;\n                    end\n                end\n                \n                COMPUTE_RESULT: begin\n                    even_candidate = L * 2'd2;\n                    odd_candidate = d_found ? ((d_reg << 1) + 8'd1) : 8'd255;\n                    result <= (even_candidate < odd_candidate) ? even_candidate : odd_candidate;\n                    state <= DONE_STATE;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule